import{V as t}from"./chunks/theme.C0QilEaM.js";import{c as r,o as s,j as a,a2 as n,a as l,G as o,k as i}from"./chunks/framework.DDIT__tB.js";const d={class:"tip custom-block"},g=JSON.parse('{"title":"📊 Model: (AccessControl-ABAC)","description":"","frontmatter":{},"headers":[],"relativePath":"examples/models/dfd/AC-ABAC-violation.md","filePath":"examples/models/dfd/AC-ABAC-violation.md"}'),c={name:"examples/models/dfd/AC-ABAC-violation.md"},p=Object.assign(c,{setup(h){return(u,e)=>(s(),r("div",null,[e[2]||(e[2]=a("h1",{id:"📊-model-accesscontrol-abac",tabindex:"-1"},[l("📊 Model: (AccessControl-ABAC) "),a("a",{class:"header-anchor",href:"#📊-model-accesscontrol-abac","aria-label":'Permalink to "📊 Model: (AccessControl-ABAC)"'},"​")],-1)),a("div",d,[e[0]||(e[0]=a("p",{class:"custom-block-title"},"Available Online",-1)),e[1]||(e[1]=a("p",null,"This model is available to view using the online editor!",-1)),o(i(t),{text:"Open In Online Editor (No Violation)",href:"https://editor.dataflowanalysis.org/?file=https://raw.githubusercontent.com/DataFlowAnalysis/DataFlowAnalysis/refs/heads/main/bundles/org.dataflowanalysis.examplemodels/scenarios/dfd/AC-abac-no-violation/abac-no-violation.json"}),o(i(t),{text:"Open In Online Editor (Security Violation)",href:"https://editor.dataflowanalysis.org/?file=https://raw.githubusercontent.com/DataFlowAnalysis/DataFlowAnalysis/refs/heads/main/bundles/org.dataflowanalysis.examplemodels/scenarios/dfd/AC-abac-violation/abac-violation.json"})]),e[3]||(e[3]=n('<h2 id="🔗-link-to-original-paper-article" tabindex="-1">🔗 Link to Original Paper/Article <a class="header-anchor" href="#🔗-link-to-original-paper-article" aria-label="Permalink to &quot;🔗 Link to Original Paper/Article&quot;">​</a></h2><p><a href="https://doi.org/10.1016/j.jss.2021.111138" target="_blank" rel="noreferrer">View Full Main Source</a></p><p><a href="https://github.com/DataFlowAnalysis/DataFlowAnalysis/tree/main/bundles/org.dataflowanalysis.examplemodels/scenarios/pcm/BankBranches" target="_blank" rel="noreferrer">Open Example Model in Example Models Bundles</a></p><h2 id="📝-short-description" tabindex="-1">📝 Short Description <a class="header-anchor" href="#📝-short-description" aria-label="Permalink to &quot;📝 Short Description&quot;">​</a></h2><p>This Model represents a bank managing two different branches in the US and Asia. Normal Customers can be registered by clerks, meanwhile celebrities get registered by managers. Clerks are also able to use the system to determine the credit line a customer might be able to get. Additionally, managers are able to search for customers and move them to a different region</p><h2 id="🔤-abbreviations" tabindex="-1">🔤 Abbreviations <a class="header-anchor" href="#🔤-abbreviations" aria-label="Permalink to &quot;🔤 Abbreviations&quot;">​</a></h2><h2 id="📖-extensive-description-if-possible" tabindex="-1">📖 Extensive Description (if possible) <a class="header-anchor" href="#📖-extensive-description-if-possible" aria-label="Permalink to &quot;📖 Extensive Description (if possible)&quot;">​</a></h2><p>Entry points to the system are either accesses by clerks (<code>Role.Clerk</code>) or managers (<code>Role.Managers</code>) in one of the two regions the bank operates in (either <code>Location.USA</code> or <code>Location.Asia</code>) Customers can be registered by calling the <code>registerCustomer</code> function. Clerks are also able to determine the credit line of customers using <code>determineCreditLine</code>. Lastly, using <code>findCustomer</code> clerks can find customers in the backend of the system.</p><p>Managers are also able to register customers using <code>registerCustomer</code> in order to register celebrities. Additionally, they can use <code>moveCustomer</code> to move customers between the different regions of the bank.</p><p>The backend consists of three basic components: The <code>CustomerHandling</code> component is responsible for registering customers and determining customer credit lines. The <code>CustomerMovement</code> component is used when customers are moved between regions. Lastly, the <code>CustomerStore</code> component stores the data of customers in a database.</p><h2 id="🏷️-label-description" tabindex="-1">🏷️ Label description <a class="header-anchor" href="#🏷️-label-description" aria-label="Permalink to &quot;🏷️ Label description&quot;">​</a></h2><ul><li><h3 id="🗂️-data-labels" tabindex="-1">🗂️ Data Labels: <a class="header-anchor" href="#🗂️-data-labels" aria-label="Permalink to &quot;🗂️ Data Labels:&quot;">​</a></h3><ul><li><h3 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h3><ul><li><strong>USA</strong>: Data originating from the United States</li><li><strong>Asia</strong>: Data originating from Asia</li></ul></li></ul></li><li><h3 id="🏷️-node-labels" tabindex="-1">🏷️ Node Labels: <a class="header-anchor" href="#🏷️-node-labels" aria-label="Permalink to &quot;🏷️ Node Labels:&quot;">​</a></h3><ul><li><h3 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h3><ul><li><strong>USA</strong>: Bank Branch Location in the United States</li><li><strong>Asia</strong>: Bank Branch Location in Asia</li></ul></li><li><h3 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h3><ul><li><strong>Clerk</strong>: System managed and accessible by a bank clerk</li><li><strong>Manager</strong>: System managed and accessible to a manager</li></ul></li><li><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h3><ul><li><strong>Regular</strong>: Customer is a regular customer</li><li><strong>Celebrity</strong>: Customer is a celebrity</li></ul></li></ul></li></ul><h2 id="⚠️-constraints" tabindex="-1">⚠️ Constraints <a class="header-anchor" href="#⚠️-constraints" aria-label="Permalink to &quot;⚠️ Constraints&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><p>Clerks are not supposed to be able to access Celebrity customer data. <code>- Security: data DataStatus.Celebrity neverFlows vertex NodeRole.Clerk</code></p><h2 id="🚨-violations" tabindex="-1">🚨 Violations <a class="header-anchor" href="#🚨-violations" aria-label="Permalink to &quot;🚨 Violations&quot;">​</a></h2><p>Although no violations were found in the original architecture, we have slightly modified the diagram to produce one alternate version in which violations are introduced:</p><ul><li>The introduced flow <em>celebrity_customer_details</em> lets <code>Celebrity</code> data flow into the normal <strong>Customer Storage</strong>, which the <strong>Clerk US</strong> can access.</li></ul>',18))]))}});export{g as __pageData,p as default};
